mapper.insert:

INSERT INTO cart
(
    member_id,
    product_id,
    quantity
)
VALUES
(
    #{memberId},
    #{productId},
    #{quantity}
);

mapper.update:
UPDATE cart
SET quantity = #{quantity}
WHERE member_id = #{memberId}
  AND product_id = #{productId};

UPDATE cart
SET quantity = quantity + 1
WHERE member_id = #{memberId}
  AND product_id = #{productId};

UPDATE cart
SET quantity = quantity - 1
WHERE member_id = #{memberId}
  AND product_id = #{productId}
  AND quantity > 1;

mapper.delete:
DELETE FROM cart
WHERE member_id = #{memberId}
  AND product_id = #{productId};
